function rlpvInitModal(){
  const box=document.getElementById('rlpvBox'); if(!box||box._bound) return; box._bound=true;
  document.getElementById('rlpvCancel').addEventListener('click',function(){ box.style.display='none'; });
  box.addEventListener('click',function(e){ if(e.target===box) box.style.display='none'; });
  // digitar o nº do PV: valida contra os destinos possíveis (regra: só PVs com saldo)
  document.getElementById('rlpvDig').addEventListener('input',function(){
    const q=this.value.trim(); const w=document.getElementById('rlpvWarn');
    if(!q){ w.style.display='none'; return; }
    const o=pvLookup(q);
    const ok=o && o.itens.some(function(r){ return r.codigo===box.dataset.cod; }) && String(o.pv)!==String(box.dataset.pvde);
    if(!ok){
      w.style.display='block';
      w.textContent='PV '+q+' não é destino válido: não tem saldo a entregar do produto '+box.dataset.cod+' (ou é o próprio PV de origem).';
    } else { w.style.display='none'; }
  });
  document.getElementById('rlpvOk').addEventListener('click',function(){
    const cod=box.dataset.cod, pvDe=box.dataset.pvde, qtdMax=Number(box.dataset.qtdmax)||0;
    if(!cod||!pvDe) return;
    const qtd=Number(document.getElementById('rlpvQtd').value)||0;
    if(qtd<=0){ alert('Informe a quantidade.'); return; }
    if(qtd>qtdMax){ alert('Qtd maior que o saldo do PV '+pvDe+' ('+NF.format(qtdMax)+' un).'); return; }
    let pvPara='';
    const dig=document.getElementById('rlpvDig').value.trim();
    const sel=document.getElementById('rlpvSel').value;
    if(dig){
      const o=pvLookup(dig);
      const ok=o && o.itens.some(function(r){ return r.codigo===cod; }) && String(o.pv)!==String(pvDe);
      if(!ok){ alert('PV '+dig+' não é destino válido — só PVs com saldo a entregar do produto '+cod+' (regra).'); return; }
      pvPara=String(o.pv);
    } else if(sel){
      pvPara=sel.split('|')[0];
    } else { alert('Escolha o PV destino (lista ou digite o nº).'); return; }
    const dest=rlpvDestinos(cod,pvDe).find(function(o){ return String(o.pv)===String(pvPara); });
    if(!dest){ alert('PV '+pvPara+' sem saldo a entregar deste produto — realocação indisponível.'); return; }
    if(qtd>dest.livre){ alert('PV '+pvPara+' tem só '+NF.format(dest.livre)+' un de saldo livre — realocação limitada a isso.'); return; }
    const regs=rlpvRegs(cod);
    regs.push({cod:String(cod), de:String(pvDe), para:String(pvPara), qtd:qtd, data:box.dataset.data||progDate||'', quando:new Date().toISOString()});
    rlpvSave(cod, regs);
    box.style.display='none';
    progBuildFromDecls(); renderProgTabela(); renderKpis(); renderGantt(); renderTimeline(); renderTabela();
    const st=document.getElementById('declStatus'); if(st) st.textContent='PV '+pvDe+' → PV '+pvPara+': '+NF.format(qtd)+' un realocadas ('+cod+') · produção não muda · nada gravado no MaxiProd';
    alert('Realocado: '+NF.format(qtd)+' un do PV '+pvDe+' → PV '+pvPara+' ('+cod+'). A produção continua igual — mudou só o destino. Ctrl+Z desfaz.');
  });
}
