window._rlpvCache = (function(){ try{ return JSON.parse(localStorage.getItem('rlpv|all')||'{}'); }catch(e){ return {}; } })();
function rlpvAllLoad(){
  // carrega as realocações de TODOS os códigos (localStorage) para o cache da sessão
  const all={};
  try{
    for(let i=0;i<localStorage.length;i++){
      const k=localStorage.key(i);
      if(k && k.indexOf('rlpv|')===0 && k!=='rlpv|all'){
        const cod=k.slice(5);
        const a=JSON.parse(localStorage.getItem(k)||'[]');
        if(Array.isArray(a)&&a.length) all[cod]=a;
      }
    }
  }catch(e){}
  return all;
}
let rlpvCache = rlpvAllLoad();
function renderAProg(){
  const prog = {}; // codigo -> {prog: un, det: [str]}
  declDaUnid().forEach(function(d){
    if(d.status==='Cancelado'||!d.cod||!d.data||Number(d.qtd)<=0) return;
    const o = prog[d.cod] = prog[d.cod] || {prog:0, det:[]};
    o.prog += Number(d.qtd);
    o.det.push(dtBR(d.data)+' ×'+NF.format(Number(d.qtd))+(d.pv?' · PV '+d.pv:'')+(d.local==='V'?' · V':' · C')+(d.status&&d.status!=='Planejado'?' · '+d.status:''));
  });
  const map = {};
  DATA.rows.forEach(function(r){
    const o = map[r.codigo] = map[r.codigo] || {desc:r.desc,frete:r.frete,saldo:0,vt:0,pvs:new Set(),entrega:'',prog:0,det:[]};
    o.saldo += Number(r.qtd)||0; o.vt += r.vtot||0; o.pvs.add(r.pv+'|'+r.empresa);
    if(!o.entrega || (r.iso&&r.iso<o.entrega)) o.entrega = r.iso;
    const p = prog[r.codigo];
    if(p){ o.prog = p.prog; o.det = p.det; }
  });
  // SMKT: produto pronto é real (regra Dante 27/09) — saldo no supermercado NÃO precisa ser programado
  Object.keys(map).forEach(function(cod){
    try{ map[cod].smkt = Math.max(0, Number(smktSaldo(cod))||0); }catch(e){ map[cod].smkt = 0; }
  });
  const q = apQ.toUpperCase();
  const arr = Object.entries(map)
    .map(function(e){ const [cod,o] = e; o.aProg = disponivelProg(cod); return [cod,o]; })
    .filter(function(e){ const [cod,o] = e; return o.saldo>0 && (!q || (cod+' '+o.desc).toUpperCase().includes(q)); })
    .sort(function(a,b){ return b[1].aProg - a[1].aProg || b[1].vt - a[1].vt; });
  let tS=0,tP=0,tA=0,tV=0,tSm=0;
  const rows = arr.map(function(e){
    const [cod,o] = e;
    tS+=o.saldo; tP+=Math.min(o.prog,o.saldo); tA+=o.aProg; tV+=o.vt; tSm+=(o.smkt||0);
    const progTxt = (o.det.length ? o.det.join(' + ') : '<span style="color:var(--mut)">—</span>') + ((o.smkt||0)>0 ? ' <span class="tagP">🛒 SMKT ×'+NF.format(o.smkt)+'</span>' : '');
    const sug = apSugerirData();
    const draggable = o.aProg>0 ? ' draggable="true" data-apcod="'+cod+'" data-apqtd="'+o.aProg+'" title="Arraste até um dia acima para programar (pergunta a qtd)"' : '';
    const btn = o.aProg>0 ? '<button class="exRl" data-apbtn="'+cod+'" data-apqtd="'+o.aProg+'" title="Programar: escolhe data e qtd">📅 Programar</button>' : '';
    return '<tr'+draggable+'><td><div class="cod">'+cod+(o.frete?' <span class="tagF">FRETE</span>':'')+'</div><div class="dsc">'+o.desc.slice(0,52)+'</div>'+btn+'</td>'+
      '<td class="num">'+NF.format(o.saldo)+'</td><td class="num">'+FMT.format(o.vt)+'</td>'+
      '<td class="num">'+(o.prog?NF.format(Math.min(o.prog,o.saldo)):'—')+'</td>'+
      '<td class="num" style="font-weight:800;color:'+(o.aProg>0?'#b45309':'#16a34a')+'">'+NF.format(o.aProg)+'</td>'+
      '<td>'+progTxt+'</td><td class="num" style="font-weight:700;color:#1e3a8a">'+dtBR(sug)+'</td><td>'+dtBR(o.entrega)+'</td><td class="num">'+o.pvs.size+'</td></tr>';
  }).join('') || '<tr><td colspan="9">Nada encontrado.</td></tr>';
  document.getElementById('tbbAProg').innerHTML = rows;
  document.getElementById('trfAProg').innerHTML = '<td><b>TOTAL ('+arr.length+' produtos)</b></td><td class="num"><b>'+NF.format(tS)+'</b></td><td class="num"><b>'+FMT.format(tV)+'</b></td><td class="num"><b>'+NF.format(tP)+'</b></td><td class="num"><b>'+NF.format(tA)+'</b></td><td colspan="4"></td>';
}
