// ---- programação de produção da semana corrente ----
let progDia = null, progDate = null, progSemSelIso = null;
let declDraft = [];
// SUGESTÃO da próxima semana (semana sem declaração): semeia o rascunho editável com a
// fila do plano de recuperação da semana seguinte — editável como qualquer declaração.
window._sugAplicada = false;
function semearSugestaoProximaSemana(){
  if(window._sugAplicada || !DATA.progSemana || !DATA.progSemana.dias.length) return;
  const hj=new Date(); const dow=(hj.getDay()+6)%7;
  let segDate=new Date(hj); segDate.setDate(segDate.getDate()-dow);
  if(dow>=5){ segDate=new Date(hj); segDate.setDate(segDate.getDate()+(7-dow)); }
  const segIso=segDate.getFullYear()+'-'+String(segDate.getMonth()+1).padStart(2,'0')+'-'+String(segDate.getDate()).padStart(2,'0');
  const temFuturo=DATA.progSemana.dias.some(function(x){const p=String(x.data).split('/');const iso=p.length===3?p[2]+'-'+p[1]+'-'+p[0]:(p.length===2?hj.getFullYear()+'-'+p[1]+'-'+p[0]:x.data);return iso>=segIso;});
  if(temFuturo) return; // semana declarada ainda tem dias futuros — nada a semear
  // semana alvo = próxima segunda; achar a aba do plano (S##) correspondente
  const y=segDate.getFullYear(), w=(function(d){const t=new Date(d);t.setDate(t.getDate()+3);const jan4=new Date(t.getFullYear(),0,4);return 1+Math.round(((t-jan4)/86400000-3+((jan4.getDay()+6)%7))/7);})(segDate);
  const alvo='S'+String(w).padStart(2,'0');
  const linhas=window.PLANO_SEMANA&&window.PLANO_SEMANA[alvo];
  if(!linhas||!linhas.length){ window._sugAplicada=true; return; }
  const nomeDia=['Domingo','Segunda','Terça','Quarta','Quinta','Sexta','Sábado'];
  const diasUteis=[];
  for(let i=0;i<5;i++){const d=new Date(segDate);d.setDate(d.getDate()+i);diasUteis.push(d);}
  // distribui produtos (maior qtd primeiro) equilibrando carga nos 5 dias úteis
  const carga=[0,0,0,0,0];let n=0;
  linhas.slice().sort(function(a,b){return b.qtd-a.qtd;}).forEach(function(L){
    let mi=0;for(let i=1;i<5;i++){if(carga[i]<carga[mi])mi=i;}
    carga[mi]+=L.qtd;
    const d=diasUteis[mi];
    const iso=d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');
    declDraft.push({dia:nomeDia[d.getDay()],data:iso,cod:L.cod,qtd:L.qtd,local:window.UNID||'C',pv:L.pv||'',id:'PR-SUG-'+(n++),obs:'SUGESTÃO do plano de recuperação ('+alvo+') — confirmar',status:'Planejado'});
  });
  if(n){ declSave(); }
  window._sugAplicada=true;
}
