    const smSelo = smLinha>0 ? '<span class="tagF" style="background:#fee2e2;color:#991b1b" title="Este produto tem '+NF.format(smLinha)+' un no estoque SMKT (produto pronto) — abatem a programação">🛒 SMKT '+NF.format(smLinha)+'</span> ' : '';
