    const hj=new Date(); const hojeISO=hj.getFullYear()+'-'+String(hj.getMonth()+1).padStart(2,'0')+'-'+String(hj.getDate()).padStart(2,'0');
    const excessos=[];
    // 1) fósseis: declaração cujo código/PV não tem saldo na carteira (some da programação) — SÓ DE HOJE EM DIANTE (passado é histórico)
    const fos=(window.fosseisCache||[]).filter(function(x){ return progIso(x.data)>=hojeISO; });
    fos.forEach(function(x){ excessos.push({tipo:'fossil', cod:x.cod, qtd:x.qtd, data:x.data, motivo:x.motivo}); });
