// ---- copiar/colar e mover linha (card principal) ----
function progIso(d){ // aceita ISO (2026-09-30) ou dd/mm (30/09) — devolve ISO
  if(!d) return '';
  if(d.length===5){ const p=d.split('/'); return new Date().getFullYear()+'-'+p[1]+'-'+p[0]; }
  return d;
}
// v0.0.204: dias renderizados na vista atual (para o botão Empurrar achar o próximo dia)
function diasDaVista(){
  const box=document.getElementById('pbtns');
  const out=[];
  if(!box) return out;
  Array.prototype.forEach.call(box.children, function(b){
    const d=b.getAttribute('data-d'), dt=b.getAttribute('data-date');
    if(d && dt) out.push({dia:d, data:dt, iso:progIso(dt)});
  });
  return out;
}
// v0.0.205: pinta calor + mini-barras C/V nos botões de dia — chamada por renderProg E por
// renderProgTabela (toda edição de rascunho repinta na hora, sem precisar clicar no dia)
function paintProgDayButtons(){
  const pbtns=document.getElementById('pbtns');
  if(!pbtns || !pbtns.children.length) return;
  const cargaDia={};
  const fos=(window.fosseisCache||[]);
  declDaUnid().forEach(function(d){
    if(d.status==='Cancelado'||!d.data||Number(d.qtd)<=0) return;
    const iso=progIso(d.data);
    if(fos.some(function(f){return f.cod===d.cod&&progIso(f.data)===iso;})) return; // fóssil não conta (igual ao card)
    cargaDia[iso]=(cargaDia[iso]||0)+Number(d.qtd);
  });
  const maxCarga=Math.max.apply(null,[1].concat(Object.keys(cargaDia).map(function(k){return cargaDia[k];})));
  Array.prototype.forEach.call(pbtns.children, function(b){
    const iso=progIso(b.getAttribute('data-date'));
    const c=cargaDia[iso]||0;
    const t=Math.round(c/maxCarga*100);
    // cor: 0=sz, 1-33=verde, 34-66=âmbar, 67-100=vermelho (relative ao dia mais cheio da vista)
    const bg = c<=0 ? '#f1f5f9' : (t<=33 ? '#dcfce7' : (t<=66 ? '#fef9c3' : '#fecaca'));
    const fg = c<=0 ? '#94a3b8' : (t<=33 ? '#166534' : (t<=66 ? '#854d0e' : '#991b1b'));
    b.style.background=bg; b.style.color=fg;
    b.title = 'Carga: '+NF.format(c)+' un'+(c<=0?' — dia vazio':'')+' · '+t+'% do dia mais cheio';
    // divisão por FÁBRICA (Curitiba × Vinhedo) — mini-barras no rodapé do botão
    const cC=declDraft.filter(function(d){return d.status!=='Cancelado'&&progIso(d.data)===iso&&(d.local||'C')==='C'&&Number(d.qtd)>0&&!fos.some(function(f){return f.cod===d.cod&&progIso(f.data)===iso;});}).reduce(function(a,d){return a+Number(d.qtd);},0);
    const cV=declDraft.filter(function(d){return d.status!=='Cancelado'&&progIso(d.data)===iso&&(d.local||'C')==='V'&&Number(d.qtd)>0&&!fos.some(function(f){return f.cod===d.cod&&progIso(f.data)===iso;});}).reduce(function(a,d){return a+Number(d.qtd);},0);
    let inner='<div style="font-weight:800">'+b.getAttribute('data-d')+' · '+b.getAttribute('data-date')+'</div>';
    if(cC>0||cV>0){
      const tot=cC+cV, pcC=Math.round(cC/tot*100), pcV=100-pcC;
      inner+='<div style="display:flex;height:6px;width:100%;border-radius:3px;overflow:hidden;margin-top:3px">'+
        (cC>0?'<div style="width:'+pcC+'%;background:#1e3a8a"></div>':'')+(cV>0?'<div style="width:'+pcV+'%;background:#ca8a04"></div>':'')+'</div>'+
        '<div style="font-size:9.5px;font-weight:700;margin-top:2px"><span style="color:#1e3a8a">Cur '+NF.format(cC)+'</span>'+(cV>0?' · <span style="color:#a16207">Vinh '+NF.format(cV)+'</span>':'')+'</div>';
    }
    b.innerHTML=inner;
    b.style.display='inline-block'; b.style.minWidth='92px'; b.style.padding='6px 10px';
  });
}
function progCopyLine(p){
  const ex = getProgExec(p.cod, progDate) || {ok:false,qtd:0};
  const payload = {__andon:1, cod:p.cod, desc:p.desc, qtd:p.qtd, de:progDate, cut:false, exQtd:ex.qtd||0};
  const txt = JSON.stringify(payload);
  // estado setado SINCRONAMENTE (não depende da promise do clipboard)
  progCopied = payload; progCopiedTxt = txt; window.andonCut = null;
  const st=document.getElementById('declStatus'); if(st) st.textContent='Copiado: '+p.cod+' ×'+p.qtd+' ('+progDate+') — Ctrl+V para colar como nova linha ou arraste até outro dia';
  try{ if(navigator.clipboard && navigator.clipboard.writeText) navigator.clipboard.writeText(txt).catch(function(){}); }catch(x){}
}
// RECORTE: move a qtd do dia para onde colar. Com executado, transfere SÓ O SALDO (regra Dante 28/09).
function progCutLine(p){
  const ex = getProgExec(p.cod, progDate) || {ok:false,qtd:0};
  const saldo = Math.max(0, p.qtd - (ex.qtd||0));
  if(saldo<=0){ alert('Nada a recortar — a qtd realizada cobre o planejado deste dia.'); return; }
  const payload = {__andon:1, cod:p.cod, desc:p.desc, qtd:saldo, de:progDate, cut:true, exQtd:ex.qtd||0, exOk:!!ex.ok};
  const txt = JSON.stringify(payload);
  // estado setado SINCRONAMENTE (não depende da promise do clipboard)
  progCopied = payload; progCopiedTxt = txt; window.andonCut = payload;
  const st=document.getElementById('declStatus'); if(st) st.textContent='Recortado: '+p.cod+' ×'+saldo+' de '+progDate+(ex.qtd?' (executado '+ex.qtd+' fica no dia)':'')+' — Ctrl+V no dia destino';
  try{ if(navigator.clipboard && navigator.clipboard.writeText) navigator.clipboard.writeText(txt).catch(function(){}); }catch(x){}
}
function progParseCopied(t){
  if(!t) return null;
  try{ const o = JSON.parse(t); if(o && o.__andon===1 && o.cod) return o; }catch(x){}
  return null;
}
function progPasteLine(c, diaDest){
  diaDest = progIso(diaDest);
  if(!diaDest){ alert('Escolha um dia primeiro.'); return; }
  const destinoBR = diaDest.split('-').reverse().join('/');
  if(String(diaDest)===String(progIso(c.de))){ alert('Origem e destino são o mesmo dia.'); return; }
  if(c.cut){
    // TRANSFERÊNCIA via Ctrl+V: mesma regra do drop — destino recebe o saldo, origem só o executado.
    declDraft.push({dia:['Domingo','Segunda','Terça','Quarta','Quinta','Sexta','Sábado'][new Date(diaDest+'T12:00:00').getDay()], data:diaDest, cod:c.cod, qtd:c.qtd, local:window.UNID||'C', pv:'', id:'PR-CUT-'+Date.now(), obs:'transferido de '+(c.de||'?'), status:'Planejado'});
    declDraft.forEach(function(d){
      const isoD0 = progIso(d.data);
      if(d.cod===c.cod && isoD0===String(progIso(c.de)) && d.status!=='Cancelado'){
        if(c.exQtd>0){ d.qtd = Math.min(Number(d.qtd)||0, c.exQtd); d.status='Realizado'; } // mantém só o executado na origem
        else { d.qtd=0; d.status='Cancelado'; }
      }
    });
    declSave(); progBuildFromDecls(); renderDeclEditor(); progDia=null; progDate=null; renderProg();
    const st=document.getElementById('declStatus'); if(st) st.textContent=c.cod+' ×'+c.qtd+' TRANSFERIDO de '+(c.de||'?').split('-').reverse().join('/')+' → '+destinoBR+(c.exQtd?' · executado ('+c.exQtd+') permanece na origem':'')+' · nada gravado no MaxiProd';
    return;
  }
  // CÓPIA: cola como nova linha (mantém a origem intacta)
  declDraft.push({dia:['Domingo','Segunda','Terça','Quarta','Quinta','Sexta','Sábado'][new Date(diaDest+'T12:00:00').getDay()], data:diaDest, cod:c.cod, qtd:c.qtd, local:window.UNID||'C', pv:'', id:'PR-COPY-'+Date.now(), obs:'colado de '+(c.de||'?'), status:'Planejado'});
  declSave(); progBuildFromDecls(); renderDeclEditor(); progDia=null; progDate=null; renderProg();
  const st=document.getElementById('declStatus'); if(st) st.textContent='Linha colada em '+destinoBR+' · nada gravado no MaxiProd';
}
// mover a linha arrastada para o dia do botão-alvo
function progMoveTo(diaDest, dateDest){
  dateDest = progIso(dateDest);
  if(!dragP) return;
  const p = dragP;
  const ex = p.ex || {};
  const saldo = Math.max(0, p.qtd - (ex.qtd||0));
  if(saldo<=0){ alert('Nada a mover — a qtd realizada cobre o planejado.'); return; }
  if(!confirm('Transferir '+p.cod+' ×'+saldo+' un de '+(p.de||'?').split('-').reverse().join('/')+' para '+dateDest.split('-').reverse().join('/')+'?'+(ex.qtd?' (executado '+ex.qtd+' un permanece na origem)':''))) return;
  // TRANSFERÊNCIA (não cópia): mesma lógica do recorte — destino recebe o saldo, origem fica só com o executado
  progDropCutTo({__andon:1, cod:p.cod, desc:p.desc, qtd:saldo, de:p.de, cut:true, exQtd:ex.qtd||0, exOk:!!ex.ok}, dateDest);
  dragP = null;
}
// colar vindo do botão do dia (drop de recorte) — transfere saldo e zera origem
function progDropCutTo(c, dateDest){
  dateDest = progIso(dateDest);
  const destinoBR = dateDest.split('-').reverse().join('/');
  if(String(dateDest)===String(progIso(c.de))){ alert('Origem e destino são o mesmo dia.'); return; }
  // TRANSFERÊNCIA: destino recebe o saldo; origem fica SÓ com o executado (qtd mínima).
  // Executado > 0 = origem vira linha de execução (qtd = exQtd, status Realizado); sem executado = origem cancelada.
  declDraft.push({dia:['Domingo','Segunda','Terça','Quarta','Quinta','Sexta','Sábado'][new Date(dateDest+'T12:00:00').getDay()], data:dateDest, cod:c.cod, qtd:c.qtd, local:window.UNID||'C', pv:'', id:'PR-CUT-'+Date.now(), obs:'transferido de '+(c.de||'?'), status:'Planejado'});
  let origemTemExec = Number(c.exQtd)>0;
  declDraft.forEach(function(d){
    if(d.cod===c.cod && progIso(d.data)===String(progIso(c.de)) && d.status!=='Cancelado'){
      if(c.exQtd>0){ d.qtd = Math.min(Number(d.qtd)||0, c.exQtd); d.status='Realizado'; }
      else { d.qtd=0; d.status='Cancelado'; }
    }
  });
  declSave(); progBuildFromDecls(); renderDeclEditor(); progDia=null; progDate=null; renderProg();
  const st=document.getElementById('declStatus'); if(st) st.textContent=c.cod+' ×'+c.qtd+' TRANSFERIDO de '+(c.de||'?').split('-').reverse().join('/')+' → '+destinoBR+(c.exQtd?' · executado ('+c.exQtd+') permanece na origem':'')+' · nada gravado no MaxiProd';
}
