function marcarRigidas(){
  if(!DATA.rigidas || !DATA.rigidas.length) return;
  DATA.rows.forEach(function(r){
    r.rig = null;
    const pv = String(r.pv);
    const cand = DATA.rigidas.filter(function(x){ return x.pv === pv; });
    if(!cand.length) return;
    const d = (r.desc || '').toUpperCase();
    let hit = null;
    cand.forEach(function(x){
      const p = x.prod.toUpperCase();
      if(p.indexOf('MATILD')>=0 && d.indexOf('MATILD')>=0) hit = x;
      else if(p.indexOf('BERENICE')>=0 && d.indexOf('BERENICE')>=0) hit = x;
      else if(p.indexOf('KIT INDU')>=0 && d.indexOf('KIT INDU')>=0) hit = x;
      else if((p.indexOf('CARRINHO NOTEBOOK')>=0 || p.indexOf('NOTEBOOK')>=0) && (d.indexOf('NOTEBOOK')>=0)) hit = x;
      else if(p.indexOf('CARRINHO DE TRANSPORTE')>=0 && d.indexOf('TRANSPORTE')>=0) hit = x;
      else if(p.indexOf('FLOW RACK 3X2')>=0 && d.indexOf('3X2')>=0) hit = x;
      else if(p.indexOf('FLOW RACK 2X2')>=0 && d.indexOf('2X2')>=0) hit = x;
      else if(p.indexOf('ESCORREGADOR')>=0 && d.indexOf('ESCORREGADOR')>=0) hit = x;
      else if(p.indexOf('BOXING')>=0 && d.indexOf('BOXING')>=0) hit = x;
      else if(p.indexOf('CHECK IN')>=0 && d.indexOf('CHECK IN')>=0) hit = x;
      else if(p.indexOf('PACKING MONO')>=0 && d.indexOf('MONO')>=0) hit = x;
      else if(p.indexOf('PACKING MULTI')>=0 && d.indexOf('MULTI')>=0) hit = x;
      else if(p.indexOf('PACKING VOLUMOSO')>=0 && d.indexOf('VOLUMOSO')>=0) hit = x;
      else if(p.indexOf('FLOWRACK MONO')>=0 && d.indexOf('MONO')>=0) hit = x;
      else if(p.indexOf('PUT TO WALL')>=0 && d.indexOf('PUT TO WALL')>=0) hit = x;
      else if(p.indexOf('LIXEIRA')>=0 && d.indexOf('LIXEIRA')>=0) hit = x;
      else if(p.indexOf('INBOUND')>=0 && d.indexOf('INBOUND')>=0) hit = x;
      else if(p.indexOf('BLUE')>=0 && d.indexOf('BLUE')>=0) hit = x;
      else if(p.indexOf('FLOWRACK PACKING')>=0 && d.indexOf('PACKING')>=0) hit = x;
    });
    if(hit) r.rig = {iso: hit.iso, data: hit.data, cli: hit.cli, proj: hit.proj, local: hit.local};
  });
  const n = DATA.rows.filter(function(r){ return r.rig; }).length;
  console.log('Linhas marcadas RÍGIDAS:', n);
}
