const TRANSITO = {'GUARAPUAVA':[1,254],'MARINGA':[1,425],'ITAQUERA':[1,441],'MAUA':[1,445],'GRU':[1,429],'GUARULHOS':[1,429],'NOVO MUNDO':[1,420],'SAO PAULO':[1,420],'CACAPAVA':[1,520],'SAO CARLOS':[2,615],'JALES':[2,773],'BARRETOS':[2,804],'NOVA SANTA RITA':[2,751],'FLORES DA CUNHA':[2,553],'ITABORAI':[2,880],'GOIANIA':[3,1282],'MACAIBA':[4,3275],'RECIFE':[4,3074],'JOAO PESSOA':[4,3188],'ATIBAIA':[1,570],'ESTRELA':[2,690],'BRASILIA':[3,1360],'SBC':[1,400],'SP35':[1,420],'ITAPEVA':[1,470],'CONTAGEM':[3,981],'HIDROLANDIA':[3,1248],'CARIACICA':[3,1348]};
function normS(s){ return s.normalize('NFD').replace(/[̀-ͯ]/g,'').toUpperCase(); }
function cidadeDe(cli){ const c = normS(cli); for(const k in TRANSITO){ if(c.indexOf(k)>=0) return k; } return null; }
function cidadeDeOrig(cli, orig){ const tab = orig==='V' ? TRANSITO_VINHEDO : TRANSITO; const c = normS(cli); for(const k in tab){ if(c.indexOf(k)>=0) return k; } return null; }
// trânsito p/ exibição: só sai de Curitiba (Vinhedo => null = consultar transportadora)
// fim = 1º dia útil após a coleta (finalização prevista da produção); cheg = chegada no cliente
function trDe(local, cli, dataBr){
  if(local === 'Vinhedo') return null;
  const cid = cidadeDe(cli);
  if(!cid || !dataBr || dataBr.length !== 10) return null;
  const ent = new Date(dataBr+'T12:00:00');
  const coleta = subDU(ent, TRANSITO[cid][0]);
  const fim = addDU(coleta, 1);
  const cheg = addDU(fim, TRANSITO[cid][0] - 1);
  return {fim: dtBR(isoD(fim)), cheg: dtBR(isoD(cheg)), coleta: dtBR(isoD(coleta))};
}
function addDU(d,n){ const x=new Date(d); let i=0; while(i<n){ x.setDate(x.getDate()+1); const w=x.getDay(); if(w>0&&w<6) i++; } return x; }
function subDU(d,n){ const x=new Date(d); let i=0; while(i<n){ x.setDate(x.getDate()-1); const w=x.getDay(); if(w>0&&w<6) i++; } return x; }
function brD(d){ return String(d.getDate()).padStart(2,'0')+'/'+String(d.getMonth()+1).padStart(2,'0'); }
function isoD(d){ return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0'); }
// segunda-feira da semana "S39 · 21.09-25.09" (label do botão)
function semanaSegunda(label){
  const m = String(label||'').match(/(\d{2})\.(\d{2})-(\d{2})\.(\d{2})/);
  if(!m) return null;
  const y = new Date().getFullYear();
  return y + '-' + m[2] + '-' + m[1];
}

function sugestoesSemana(){
  const hoje = new Date(); hoje.setHours(0,0,0,0);
  const seg = new Date(hoje); const dw = hoje.getDay()===0 ? 7 : hoje.getDay();
  seg.setDate(hoje.getDate() - (dw-1)); // segunda desta semana
  const sex = new Date(seg); sex.setDate(seg.getDate()+4);
  const out = [];
  DATA.rows.forEach(function(r){
    if(!r.iso || r.frete) return;
    const cid = cidadeDe(r.cliente);
    if(!cid) return;
    const tdu = TRANSITO[cid][0];
    const alvoIso = (r.rig && r.rig.iso) ? r.rig.iso : r.iso; // data rígida manda quando existe
    const ent = new Date(alvoIso + 'T12:00:00');
    const coleta = subDU(ent, tdu);   // coleta máxima para chegar no dia
    if(coleta < seg || coleta > sex) return;
    out.push({row:r, cid:cid, tdu:tdu, km:TRANSITO[cid][1], coleta:coleta, prod:subDU(coleta,1), alvoIso:alvoIso});
  });
  out.sort(function(a,b){ return a.row.iso.localeCompare(b.row.iso); });
  return out;
}

