function smktHistorySave(h){ localStorage.setItem('smkt|historico',JSON.stringify(h||[])); if(window.ANDON_SYNC&&window.ANDON_SYNC.connected()){ localStorage.setItem('andon|smkt-rev',String(Date.now())); window.ANDON_SYNC.pushSmkt(smktEntradas(),h||[]).catch(function(){}); } }
