function smktConsume(cod,q,evento,meta){
  q=Math.max(0,Number(q)||0);const ents=smktEntradas();let need=q;
  for(let i=0;i<ents.length&&need>0;i++)if(String(ents[i].cod)===String(cod)){const take=Math.min(need,Number(ents[i].qtd)||0);ents[i].qtd-=take;need-=take;}
  smktSave(ents.filter(function(x){return Number(x.qtd)>0.0001;}),[]);
  if(q>0){const h=smktHistory();h.unshift(Object.assign({data:new Date().toLocaleDateString('pt-BR'),cod:String(cod),qtd:q,event:evento},meta||{}));smktHistorySave(h);}
  return need<=0.0001;
}
function smktEnsureMigrated(){
 if(localStorage.getItem('smkt|v3-migrated')==='1')return;
 let ents=[];try{ents=JSON.parse(localStorage.getItem('smkt|entradas')||'[]');}catch(e){}
 let alcs=[];try{alcs=JSON.parse(localStorage.getItem('smkt|alocs')||'[]');}catch(e){}
 const h=smktHistory();let keep=[];
 (Array.isArray(ents)?ents:[]).forEach(function(x){if(!x||!x.cod||!(Number(x.qtd)>0))return;h.unshift({data:x.data||new Date().toLocaleDateString('pt-BR'),cod:String(x.cod),qtd:Number(x.qtd),event:'Saldo legado arquivado — origem não confirmada',motivo:'Não foi entrada manual confirmada por Dante; removido do saldo ativo.'});});
 (Array.isArray(alcs)?alcs:[]).forEach(function(a){if(a&&a.cod&&Number(a.qtd)>0)h.unshift({data:a.data||new Date().toLocaleDateString('pt-BR'),cod:String(a.cod),qtd:Number(a.qtd),event:'Alocação legada — histórico',pv:String(a.pv||''),nf:a.nf||'',motivo:a.obs||''});});
 smktSave([],[]);smktHistorySave(h);localStorage.setItem('smkt|v3-migrated','1');
}
function smktNFStatus(cod){
 // SEMI-AUTOMÁTICO (v0.0.236, regra Dante 06/10): a NF NÃO consome o saldo sozinha.
 // Quando a NF fecha o saldo do PV no ERP (ele sai da carteira), o Andon ALERTA:
 // "NF precisa de saldo" — a alocação (do SMKT ou da produção declarada) é manual, da PCP.
 // Registros de alerta resolvido ficam em 'smkt|nf-resolvido' = [{cod,pv,nf,qtd,fonte,data}].
 // SOMENTE ITENS FUTUROS (regra Dante 06/10 13h54): NF que fechou PV com entrega PASSADA
 // é histórico — não entra no alerta. Data de entrega do item vem do nf_baixadas.json.
 const hj = new Date();
 const hjIso = hj.getFullYear()+'-'+String(hj.getMonth()+1).padStart(2,'0')+'-'+String(hj.getDate()).padStart(2,'0');
 const ent=smktEntradas().filter(function(x){return String(x.cod)===String(cod);}).reduce(function(a,x){return a+(Number(x.qtd)||0);},0);
 const detNF=[];
 let pend=0;
 try{
   const resolv=smktNfResolvidos();
   nfLista().forEach(function(n){
     (Array.isArray(n.itens)?n.itens:[]).forEach(function(i){
       if(String(i.cod)!==String(cod)) return;
       const pv=String(i.pv||'');
       if(String(i.entrega||'') && String(i.entrega)<hjIso) return; // entrega passada = histórico
       // pendente: NF fechou o PV na carteira (não existe mais linha com saldo para ele)
       const naCarteira=DATA.rows.some(function(r){ return String(r.pv)===pv && r.codigo===cod; });
       if(naCarteira) return; // PV ainda tem saldo — a NF foi parcial, saiu sozinho
       const jaResolvido=resolv.some(function(x){ return String(x.cod)===String(cod)&&String(x.pv)===pv&&String(x.nf)===String(n.nf); });
       const usado=Number(i.qtd)||0;
       if(jaResolvido) return;
       detNF.push({nf:String(n.nf),pv:pv,qtd:usado,data:n.data||'',usado:usado,entrega:String(i.entrega||'')});
       pend+=usado;
     });
   });
 }catch(e){}
 return {ent:ent,saiuNF:0,detNF:detNF,alocado:0,saldo:Math.max(0,ent),alocs:[],pendNF:pend};
}
function smktNfResolvidos(){ try{ const a=JSON.parse(localStorage.getItem('smkt|nf-resolvido')||'[]'); return Array.isArray(a)?a:[]; }catch(e){ return []; } }
function smktNfResolvidoSave(a){ try{ localStorage.setItem('smkt|nf-resolvido',JSON.stringify(a||[])); }catch(e){} if(window.ANDON_SYNC&&window.ANDON_SYNC.connected()){ localStorage.setItem('andon|smkt-rev',String(Date.now())); try{ window.ANDON_SYNC.pushSmkt(smktEntradas(),smktHistory(),a||[]).catch(function(){}); }catch(e){} } }
