// DESFAZER: reverte um evento específico do histórico (por índice) — corrige qualquer erro.
function smktUndo(evIdx){
 smktEnsureMigrated();
 const h=smktHistory();
 let i=(typeof evIdx==='number')?evIdx:0;
 if(h[i]&&h[i].undone){document.getElementById('smUndoInfo').textContent='Este evento já foi desfeito.';return;}
 if(i>=h.length||!h[i]){document.getElementById('smUndoInfo').textContent='Nada a desfazer.';return;}
 const ev=h[i];
 const ents=smktEntradas();
 if(ev.event==='Entrada via programação (destino SMKT)'){
  // desfazer a entrada: remove as unidades do saldo SOMANDO as que voltaram por
  // desfazer de alocação/retirada (ledger consistente — nunca deixa resíduo).
  const k='prog:'+String(ev.cod)+'|'+(String(ev.motivo||'').split('dia ')[1]||'');
  let rest=Number(ev.qtd)||0;
  for(let j=ents.length-1;j>=0&&rest>0;j--){if(String(ents[j].origem||'')===k){const t=Math.min(rest,Number(ents[j].qtd)||0);ents[j].qtd-=t;rest-=t;}}
  for(let j=ents.length-1;j>=0&&rest>0;j--){if(String(ents[j].origem||'')==='undo'&&String(ents[j].cod)===String(ev.cod)){const t=Math.min(rest,Number(ents[j].qtd)||0);ents[j].qtd-=t;rest-=t;}}
  for(let j=0;j<ents.length&&rest>0;j++){if(String(ents[j].cod)===String(ev.cod)){const t=Math.min(rest,Number(ents[j].qtd)||0);ents[j].qtd-=t;rest-=t;}}
  const rem=ents.filter(function(x){return Number(x.qtd)>0.0001;});
  smktSave(rem,[]);
  if(rest>0.0001){document.getElementById('smUndoInfo').textContent='Parcial: '+NF.format(Number(ev.qtd)-rest)+' de '+NF.format(ev.qtd)+' un (o resto já saiu por alocação/retirada).';}
  else{document.getElementById('smUndoInfo').textContent='Desfeita a entrada de '+ev.cod+' ×'+NF.format(ev.qtd)+'.';}
  ev.undone=true;ev.motivo=(ev.motivo||'')+' [DESFEITO]';
 }else if(ev.event==='Entrada manual'){
  let rest=Number(ev.qtd)||0;
  for(let j=0;j<ents.length&&rest>0;j++){if(String(ents[j].cod)===String(ev.cod)){const t=Math.min(rest,Number(ents[j].qtd)||0);ents[j].qtd-=t;rest-=t;}}
  smktSave(ents.filter(function(x){return Number(x.qtd)>0.0001;}),[]);
  if(rest>0.0001){document.getElementById('smUndoInfo').textContent='Parcial: '+NF.format(Number(ev.qtd)-rest)+' de '+NF.format(ev.qtd)+' un (o resto já saiu por alocação/retirada).';}
  else{document.getElementById('smUndoInfo').textContent='Desfeita a entrada de '+ev.cod+' ×'+NF.format(ev.qtd)+'.';}
  ev.undone=true;ev.motivo=(ev.motivo||'')+' [DESFEITO]';
 }else if(ev.event==='Alocado em PV'){
  // devolve as unidades À ENTRADA ORIGINAL do produto (não cria entrada órfã) —
  // assim desfazer a entrada depois remove tudo de forma consistente.
  const e2=smktEntradas();let devolvido=false;
  for(let j=0;j<e2.length&&!devolvido;j++){if(String(e2[j].cod)===String(ev.cod)){e2[j].qtd=(Number(e2[j].qtd)||0)+(Number(ev.qtd)||0);devolvido=true;}}
  if(!devolvido)e2.push({cod:String(ev.cod),qtd:Number(ev.qtd)||0,origem:'undo',data:new Date().toLocaleDateString('pt-BR')});
  smktSave(e2,[]);
  document.getElementById('smUndoInfo').textContent='Desfeita a alocação: '+ev.cod+' ×'+NF.format(ev.qtd)+' voltou ao saldo (PV '+ev.pv+' desalocado).';
  ev.undone=true;ev.motivo=(ev.motivo||'')+' [DESFEITO]';
 }else if(ev.event==='Retirada manual'){
  const e2=smktEntradas();let devolvido=false;
  for(let j=0;j<e2.length&&!devolvido;j++){if(String(e2[j].cod)===String(ev.cod)){e2[j].qtd=(Number(e2[j].qtd)||0)+(Number(ev.qtd)||0);devolvido=true;}}
  if(!devolvido)e2.push({cod:String(ev.cod),qtd:Number(ev.qtd)||0,origem:'undo',data:new Date().toLocaleDateString('pt-BR')});
  smktSave(e2,[]);
  document.getElementById('smUndoInfo').textContent='Desfeita a retirada: '+ev.cod+' ×'+NF.format(ev.qtd)+' voltou ao saldo.';
  ev.undone=true;ev.motivo=(ev.motivo||'')+' [DESFEITO]';
 }else if(ev.event==='Consumo via NF'){
  document.getElementById('smUndoInfo').textContent='Consumo via NF '+ev.nf+' não é reversível aqui — a NF é fato do MaxiProd. Use "Alocar" para devolver ao PV ou "+ Entrada no SMKT" para repor.';
  return;
 }else{
  document.getElementById('smUndoInfo').textContent='Evento "'+ev.event+'" não tem desfazer automático.';
  return;
 }
 smktHistorySave(h);
 renderSmkt();renderProgTabela();
}
