// ---- resumo por produto ----
let sortKey='total', sortAsc=false;
function renderTabela(){
  const inc = document.getElementById('chkFrete2').checked;
  const q = document.getElementById('busca').value.toLowerCase();
  document.getElementById('trh').innerHTML = '<th data-k="codigo">Código/Produto</th><th data-k="tipo">Tipo</th>' +
    SEM.map(function(s,i){ return '<th data-k="i'+i+'">'+s+'</th>'; }).join('') + '<th data-k="total">Total</th>';
  Array.prototype.forEach.call(document.querySelectorAll('#trh th'), function(th){
    th.addEventListener('click', function(){ sk(th.getAttribute('data-k')); });
  });
  let ps = aggProdutos().filter(function(p){ return (inc||!p.frete) && (!q || (p.codigo+' '+p.desc).toLowerCase().indexOf(q) >= 0); });
  ps = ps.filter(function(p){ return p.total > 0.005; });
  ps.sort(function(a,b){
    let va,vb;
    if(sortKey==='codigo'){ va=a.codigo; vb=b.codigo; }
    else if(sortKey==='total'){ va=a.total; vb=b.total; }
    else if(sortKey==='tipo'){ va=a.frete?1:0; vb=b.frete?1:0; }
    else { const i = parseInt(sortKey.slice(1),10); va=val(a.cel[i].qtd,a.cel[i].vtot); vb=val(b.cel[i].qtd,b.cel[i].vtot); }
    if(typeof va==='string') return sortAsc ? va.localeCompare(vb) : vb.localeCompare(va);
    return sortAsc ? va-vb : vb-va;
  });
  const cols = SEM.map(function(s,i){ return ps.reduce(function(a,p){ return a + val(p.cel[i].qtd,p.cel[i].vtot); },0); });
  document.getElementById('tbb').innerHTML = ps.map(function(p){
    const cells = p.cel.map(function(c,i){
      const v = val(c.qtd,c.vtot);
      return '<td class="num'+(i===0&&v>0?' atrasado':'')+'">'+(v>0? fmtV(v) : '—')+'</td>';
    }).join('');
    return '<tr><td><div class="cod">'+p.codigo+'</div><div class="dsc">'+p.desc+'</div></td>'+
      '<td>'+(p.frete?'<span class="tagF">FRETE</span>':'produto')+'</td>'+cells+
      '<td class="num" style="font-weight:700">'+fmtV(p.total)+'</td></tr>';
  }).join('');
  document.getElementById('trf').innerHTML = '<td colspan="2">TOTAL ('+ps.length+' produtos)</td>' +
    cols.map(function(v){ return '<td class="num">'+fmtV(v)+'</td>'; }).join('') +
    '<td class="num">'+fmtV(ps.reduce(function(a,p){ return a+p.total; },0))+'</td>';
}
function sk(k){ if(sortKey===k) sortAsc=!sortAsc; else { sortKey=k; sortAsc=(k==='codigo'||k==='tipo'); } renderTabela(); }
document.getElementById('busca').addEventListener('input', renderTabela);

// ---- download XLSX (devolutiva: baixar, editar Data entrega, devolver com --devolutiva) ----
function dlXlsx(rows, cols, nome){
  const ws = XLSX.utils.aoa_to_sheet([cols].concat(rows));
  ws['!cols'] = cols.map(function(c){ return {wch: Math.max(12, Math.min(38, String(c).length + 6))}; });
  const wb = XLSX.utils.book_new();
  XLSX.utils.book_append_sheet(wb, ws, nome.slice(0, 30));
  XLSX.writeFile(wb, 'devolutiva_' + nome + '_' + new Date().toISOString().slice(0,10).replace(/-/g,'') + '.xlsx');
}
function dlDevolutivaItens(){
  const rs = visiveis(DATA.rows, 'chkFreteS');
  const rows = rs.map(function(r){
    return [r.iso, r.semana, r.codigo, r.desc, r.pv, r.cliente, r.empresa, r.qtd,
            (r.qtd ? +(r.vtot/r.qtd).toFixed(2) : 0), r.vtot, ''];
  });
  dlXlsx(rows, ['Data entrega','Semana','Código','Produto','PV','Cliente','Empresa','Qtd','V.unit','Valor total','Motivo'], 'itens_semana');
}
function dlDevolutivaProg(){
  const rows = DATA.progSemana.dias.map(function(a){
    return [a.dia, a.data, a.cod, a.desc, a.qtd, a.pv, a.cli, (a.emp||''), a.vtot, a.sit, ''];
  });
  dlXlsx(rows, ['Dia','Data produção','Código','Produto','Qtd','PV','Cliente','Empresa','Valor','Situação','Motivo'], 'programacao_semana');
}
