const DECL_KEY = 'andon|programacao|draft|v049';
function declLoad(){
  const sanit=function(arr){ return arr.filter(function(d){ return !(Number(d.qtd)<0); }); };
  // v0.0.311 (restauro 10/10): rascunho carrega para TODOS (leitura pública da agenda);
  // edição continua bloqueada para não-admin (viewerMode CSS + RLS admin-only)
  try{ const saved=JSON.parse(localStorage.getItem(DECL_KEY)||'null'); if(Array.isArray(saved)) return sanit(saved); }catch(e){}
  return sanit((DATA.progSemana && DATA.progSemana.declaracoes || []).map(function(d,i){return Object.assign({},d,{id:d.id||('PR-'+String(i+1).padStart(4,'0')),status:d.status||'Planejado'});}));
}
function declSave(){ // v0.0.248: sem login NÃO persiste local (leitura) — só admin grava
  try{
    const u=(JSON.parse(localStorage.getItem('andon|user')||'{}').role)||'';
    if(u!=='admin') return;
  }catch(e){ return; }
  try{localStorage.setItem(DECL_KEY,JSON.stringify(declDraft));}catch(e){}
  if(typeof progBuildFromDecls==='function')progBuildFromDecls(); }
