    tb.addEventListener('change',function(e){const x=e.target.closest('[data-decl]'); if(!x||x.dataset.decl==='del')return; const tr=x.closest('tr'),i=+tr.dataset.di; declDraft[i][x.dataset.decl]=x.value; if(x.dataset.decl==='qtd')declDraft[i].qtd=Number(x.value)||0; declSave(); progDia=null; progDate=null; renderProg();});
