    localStorage.setItem('smkt|entradas', JSON.stringify(ch.entradas));
    if(Array.isArray(ch.historico)) localStorage.setItem('smkt|historico', JSON.stringify(ch.historico));
    if(Array.isArray(ch.nfResolvidos)) localStorage.setItem('smkt|nf-resolvido', JSON.stringify(ch.nfResolvidos));
