// ==================== ABA: PROGRAMAÇÃO AUTOMÁTICA (motor de sugestão) ====================
// Sugere quando produzir cada produto para cumprir a carteira: data de entrega (item, MaxiProd),
// trânsito até o cliente, carga já declarada na agenda e capacidade diária editável.
// NADA é gravado no MaxiProd — as sugestões entram na aba Programação como declarações editáveis.
var paAlloc={}; // carga alocada pela sugestão corrente, por iso
function paDus(iniIso, fimIso){
  const out=[]; const d=new Date(iniIso+'T12:00:00'); const fim=new Date(fimIso+'T12:00:00');
  while(d<=fim){ const w=d.getDay(); if(w>0&&w<6) out.push(isoD(d)); d.setDate(d.getDate()+1); }
  return out;
}
function paSemanaDe(iso){
  const d=new Date(iso+'T12:00:00'); d.setDate(d.getDate()+3);
  const j4=new Date(d.getFullYear(),0,4);
  return 'S'+(1+Math.round(((d-j4)/86400000-3+((j4.getDay()+6)%7))/7));
}
function paLoadAtual(){
  // carga já declarada na agenda (rascunho + programação da semana), por iso
  const load={};
  (DATA.progSemana&&DATA.progSemana.dias||[]).forEach(function(x){
    if(!x.data||x.data.length!==5) return;
    const iso=new Date().getFullYear()+'-'+x.data.slice(3,5)+'-'+x.data.slice(0,2);
    load[iso]=(load[iso]||0)+(Number(x.qtd)||0);
  });
  return load;
}
function paJaDeclarado(){
  // o que já está no rascunho (cod|iso -> qtd) para não sugerir em dobro
  const m={};
  (Array.isArray(declDraft)?declDraft:[]).forEach(function(d){
    if(!d.cod||!d.data||d.status==='Cancelado') return;
    m[d.cod+'|'+d.data]=(m[d.cod+'|'+d.data]||0)+(Number(d.qtd)||0);
  });
  return m;
}
function paGerar(){
  const ini=document.getElementById('paIni').value, fim=document.getElementById('paFim').value;
  const capOn=!!(document.getElementById('paCapOn')&&document.getElementById('paCapOn').checked);
  const capC=capOn?(Math.max(1,Number(document.getElementById('paCapC').value)||40)):Infinity;
  const capV=capOn?(Math.max(0,Number(document.getElementById('paCapV').value)||0)):Infinity;
  const st=document.getElementById('paStatus');
  if(!ini||!fim||ini>fim){ alert('Informe o período (de/até).'); return; }
  const dus=paDus(ini,fim);
  if(!dus.length){ alert('O período não tem dias úteis.'); return; }
  const hojeIso=isoD(new Date());
  const start=ini<hojeIso?hojeIso:ini;
  const load=paLoadAtual(); const jaDecl=paJaDeclarado();
  const capOf=function(loc){ return loc==='V'?capV:capC; };
  // agrupa a carteira por produto
  const prods={};
  DATA.rows.forEach(function(r){
    if(r.frete) return; // frete acompanha o produto, não é programado
    let p=prods[r.codigo];
    if(!p){ p=prods[r.codigo]={cod:r.codigo,desc:r.desc,qtd:0,vtot:0,rows:[],localC:0,localV:0}; }
    p.qtd+=Number(r.qtd)||0; p.vtot+=Number(r.vtot)||0; p.rows.push(r);
    if(r.local==='Vinhedo')p.localV+=Number(r.qtd)||0; else p.localC+=Number(r.qtd)||0;
  });
  const lista=Object.values(prods).map(function(p){
    p.local=p.localV>p.localC?'V':'C';
    p.vu=p.qtd?Math.round(p.vtot/p.qtd*100)/100:0;
    // deadline = entrega mais antiga do produto; prodUntil = último dia útil de produção que ainda chega a tempo
    const first=p.rows.slice().sort(function(a,b){return a.iso.localeCompare(b.iso);})[0];
    p.deadline=first.iso; p.cliFirst=first.cliente;
    const cid=cidadeDeOrig(first.cliente, p.local);
    const tab=p.local==='V'?TRANSITO_VINHEDO:TRANSITO;
    p.tdu=cid?tab[cid][0]:0;
    let coletaMax=new Date(p.deadline+'T12:00:00');
    for(let i=0;i<p.tdu;i++) coletaMax=addDU(coletaMax,-1); // recuo os dias úteis de trânsito
    p.prodUntil=isoD(addDU(coletaMax,-1)); // produção termina no DU anterior à coleta
    p.pvs=p.rows.map(function(r){return r.pv;}).filter(function(v,i,a){return a.indexOf(v)===i;});
    return p;
  }).filter(function(p){ return p.qtd>0; });
  // ordena: mais urgente (prodUntil menor) primeiro, depois maior valor
  lista.sort(function(a,b){ return a.prodUntil.localeCompare(b.prodUntil)||b.vtot-a.vtot; });
  const sug=[]; let naoCabe=0;
  // carga por semana (para escolher a semana MENOS CARREGADA — modelo do plano de recuperação)
  const semLoad={};
  function addLoad(iso,q){ const s=paSemanaDe(iso); semLoad[s]=(semLoad[s]||0)+q; }
  Object.keys(load).forEach(function(d){ addLoad(d,load[d]||0); });
  Object.keys(paAlloc).forEach(function(d){ addLoad(d,paAlloc[d]||0); });
  lista.forEach(function(p){
    // desconta o que já está declarado deste produto (qualquer data) — evita sugerir em dobro
    let ja=0; Object.keys(jaDecl).forEach(function(k){ if(k.indexOf(p.cod+'|')===0) ja+=jaDecl[k]; });
    let need=p.qtd-ja;
    if(need<=0) return;
    const cap=capOf(p.local);
    // janela de produção: do início até prodUntil (chega a tempo); resto do período = TARDE
    const janela=dus.filter(function(d){ return d>=start&&d<=p.prodUntil; });
    const resto=dus.filter(function(d){ return d>p.prodUntil; });
    let aloc={}; // iso -> qtd
    function distribui(arr){
      let rest=need;
      for(let i=0;i<arr.length&&rest>0;i++){
        const d=arr[i];
        const room=cap-(load[d]||0)-(paAlloc[d]||0)-(aloc[d]||0);
        if(room<=0) continue;
        const q=Math.min(room,rest);
        if(q>0){ aloc[d]=(aloc[d]||0)+q; rest-=q; }
      }
      return rest;
    }
    function commit(){ for(const d in aloc){ addLoad(d,aloc[d]); } }
    let tarde=false, sobra=0;
    if(janela.length){
      // 1) tenta a SEMANA MENOS CARREGADA dentro da janela (lote inteiro — modelo aprovado)
      const sems={}; janela.forEach(function(d){ const s=paSemanaDe(d); (sems[s]=sems[s]||[]).push(d); });
      const ordem=Object.keys(sems).sort(function(a,b){ return (semLoad[a]||0)-(semLoad[b]||0)||a.localeCompare(b); });
      for(let i=0;i<ordem.length&&need>0;i++){
        const rest=distribui(sems[ordem[i]]);
        if(rest<need){ commit(); need=rest; }
        if(need<=0) break;
      }
      sobra=need;
    } else { sobra=distribui(resto); tarde=true; }
    if(sobra>0&&janela.length&&resto.length){ // não coube na janela: TARDE no resto do período
      tarde=true; sobra=distribui(resto); commit();
    }
    Object.keys(aloc).forEach(function(d){
      if(aloc[d]<=0) return;
      paAlloc[d]=(paAlloc[d]||0)+aloc[d];
      sug.push({cod:p.cod,desc:p.desc,qtd:aloc[d],iso:d,sem:paSemanaDe(d),local:p.local==='V'?'Vinhedo':'Curitiba',
        deadline:p.deadline,prodUntil:p.prodUntil,tarde:tarde,vu:p.vu,vtot:aloc[d]*p.vu,nPvs:p.pvs.length,pvs:p.pvs.join(', ')});
    });
    if(sobra>0){ naoCabe+=sobra; }
  });
  sug.sort(function(a,b){ return a.iso.localeCompare(b.iso)||a.cod.localeCompare(b.cod); });
  window._paSug=sug; window._paParams={ini:ini,fim:fim,capC:capC,capV:capV,capOn:capOn};
  paRender(sug,{dus:dus.length,naoCabe:naoCabe,capC:capC,capV:capV,capOn:capOn,ini:ini,fim:fim});
}
