let fatPvQ = '';
function renderFatPv(){
  const box = document.getElementById('fPvResult');
  const q = fatPvQ.trim().toUpperCase();
  if(!q){ box.innerHTML=''; return; }
  const rs = DATA.rows.filter(r => (String(r.pv)+' '+r.cliente+' '+r.codigo+' '+r.desc+' '+r.empresa).toUpperCase().includes(q));
  if(!rs.length){ box.innerHTML = '<div class="note" style="margin-top:8px">Nenhum item encontrado para "'+q+'".</div>'; return; }
  // agrupa por PV+empresa
  const pvs = {};
  rs.forEach(function(r){
    const k = r.pv+'|'+r.empresa;
    const o = pvs[k] = pvs[k] || {pv:r.pv, emp:r.empresa, cli:r.cliente, itens:[], vt:0, qtd:0, atr:false};
    o.itens.push(r); o.vt += vPend(r); o.qtd += qtdPend(r); if(siOf(r)===0) o.atr = true;
  });
  box.innerHTML = Object.values(pvs).sort((a,b)=>a.pv-b.pv).map(function(o){
    let fimMax='', chegMax='';
    const rows = o.itens.map(function(r){
      const trn = trDe(r.local, r.cliente, r.iso);
      if(trn){ if(trn.fim > fimMax) fimMax = trn.fim; if(trn.cheg > chegMax) chegMax = trn.cheg; }
      const vin = r.local==='Vinhedo' ? ' style="background:#FFF9C4"' : '';
      const qp2 = qtdPend(r); const zerada2 = qp2<=0;
      return '<tr'+vin+'><td><div class="cod">'+r.codigo+'</div><div class="dsc">'+r.desc.slice(0,52)+'</div></td>'+
        '<td>'+dtBR(r.iso)+(r.semana==='ATRASADO'?' <span class="tagF">ATRASADO</span>':'')+'</td>'+
        '<td class="num">'+(zerada2?'<span class="note" style="color:var(--mut)">'+NF.format(r.qtd)+' ✓</span>':NF.format(qp2))+'</td><td class="num">'+FMT.format(vPend(r)/(qp2||1))+'</td><td class="num"><b>'+FMT.format(vPend(r))+'</b></td>'+
        '<td>'+(trn?trn.fim:'—')+'</td><td>'+(trn?trn.cheg:'—')+'</td>'+
        (r.prod?'<td><span class="tagP">PRODUZIDO '+dtBR(r.prod.dmax||r.prod.dd||'')+'</span></td>':'<td></td>')+'</tr>';
    }).join('');
    return '<div class="card" style="padding:12px 14px;margin-bottom:10px">'+
      '<div style="display:flex;justify-content:space-between;flex-wrap:wrap;gap:6px;align-items:baseline;margin-bottom:6px">'+
      '<div><b style="font-size:14px">PV '+o.pv+'</b> <span class="note">· '+o.cli+' · '+o.emp+'</span>'+(o.atr?' <span class="tagF">ATRASADO</span>':'')+'</div>'+
      '<div><b style="font-size:14px">'+FMT.format(o.vt)+'</b> <span class="note">· '+NF.format(o.qtd)+' un · '+o.itens.length+' item(ns)</span></div></div>'+
      '<table class="mini" style="width:100%"><tr><th>Produto</th><th>Entrega</th><th>Qtd</th><th>V.unit</th><th>Total</th><th>Finalização prevista</th><th>Chegada no cliente</th><th>Produção</th></tr>'+rows+'</table>'+
      '<div class="note" style="margin-top:6px">⏱ Finalizar produção até: <b>'+(fimMax||'—')+'</b> &nbsp;·&nbsp; 🚚 Chegada prevista no cliente: <b>'+(chegMax||'—')+'</b></div></div>';
  }).join('');
}
