// lookup de PV na carteira — usado pelo campo "PV destino" do card Programação
function pvLookup(q){
  const s = String(q||'').trim().toUpperCase();
  if(!s) return null;
  const rs = DATA.rows.filter(function(r){ return String(r.pv)===s; });
  if(!rs.length) return null;
  const o = {pv:rs[0].pv, cli:rs[0].cliente, emp:rs[0].empresa, itens:[], qtd:0, vt:0, atr:false};
  rs.forEach(function(r){ o.itens.push(r); o.qtd+=Number(r.qtd)||0; o.vt+=Number(r.vtot)||0; if(r.semana==='ATRASADO')o.atr=true; });
  return o;
}

// carteira completa: busca + ordenação
let fatAllQ = '', fatSort = {k:'vtot', dir:-1};
// programação por código: [{data,qtd,pv,local,status}] — coluna "Programação" na aba Produtos a Faturar
const PROGMAP = DATA.progMap || {};
function progLabel(r){
  const list = PROGMAP[r.codigo];
  if(!list || !list.length) return '';
  const parts = list.map(function(d){
    const pv = d.pv ? ' · PV '+d.pv : '';
    const st = (d.status && d.status.toLowerCase()!=='planejado') ? ' · '+d.status : '';
    return dtBR(d.data)+' ×'+NF.format(d.qtd)+pv+st;
  });
  return parts.join(' + ');
}
function renderFatAll(){
  const q = fatAllQ.toUpperCase();
  let rs = DATA.rows.filter(r => !q || (r.codigo+' '+r.desc+' '+r.cliente+' '+r.pv+' '+r.empresa+' '+r.iso).toUpperCase().includes(q));
  const k = fatSort.k, dir = fatSort.dir;
  rs.sort(function(a,b){ let x=a[k],y=b[k]; if(typeof x==='string'){return x.localeCompare(y)*dir;} return ((x||0)-(y||0))*dir; });
  rs.forEach(function(r){ const t = trDe(r.local, r.cliente, r.iso); r.cheg = t ? t.cheg : ''; });
  document.getElementById('fAll').innerHTML = rs.map(function(r){
    const vin = r.local==='Vinhedo' ? ' style="background:#FFF9C4"' : '';
    const prog = progLabel(r);
    const plano = (r.semana==='ATRASADO' && r.siPlano!=null) ? ' <span class="tagS">Plano S'+DATA.semanas[r.siPlano].slice(1,3)+'</span>' : '';
    const qp = qtdPend(r), vp = vPend(r);
    const prodQ = r.qtd - qp;
    const prodTxt = prodQ>0 ? ' <span class="tagP">'+NF.format(prodQ)+' prod/SMKT</span>' : '';
    return '<tr'+vin+'><td>'+dtBR(r.iso)+(r.semana==='ATRASADO'?' <span class="tagF">ATRASADO</span>':'')+'</td>'+
      '<td><div class="cod">'+r.codigo+'</div><div class="dsc">'+r.desc.slice(0,60)+'</div></td>'+
      '<td><b>'+r.pv+'</b></td><td>'+r.cliente+'</td><td>'+r.empresa+'</td><td>'+r.local+'</td><td>'+(r.cheg||'—')+'</td>'+
      '<td class="num">'+NF.format(qp)+'</td><td class="num">'+FMT.format(vp/(qp||1))+'</td><td class="num"><b>'+FMT.format(vp)+'</b>'+prodTxt+'</td>'+
      '<td>'+(prog?'<span class="tagP">'+prog+'</span>':plano||'<span style="color:var(--mut)">—</span>')+'</td></tr>';
  }).join('');
}
