// campo "PV destino" digitável: ao digitar o nº, o Andon traz as informações do PV
document.addEventListener('input', function(e){
  const inp = e.target.closest ? e.target.closest('#tbbP input[data-p="pvdig"]') : null;
  if(!inp) return;
  const tr = inp.closest('tr'); const ix = parseInt(tr.getAttribute('data-ix'),10);
  const p = progProdsCache[ix]; if(!p) return;
  const info = tr.querySelector('[data-p="pvdiginfo"]');
  const q = inp.value.trim();
  if(!q){ if(info){ info.style.display='none'; info.textContent=''; } return; }
  const o = pvLookup(q);
  if(info){
    if(o){
      const itens = o.itens.map(function(r){ return r.desc ? r.desc.slice(0,28) : r.codigo; }).slice(0,2).join(', ');
      info.innerHTML = '<b>PV '+o.pv+'</b> · '+o.cli+' · '+o.emp+'<br>'+o.itens.length+' item(ns): '+itens+'<br>Saldo: <b>'+NF.format(o.qtd)+' un</b> · '+FMT.format(o.vt)+'<br>Entrega: '+o.itens.map(function(r){return dtBR(r.iso);}).slice(0,2).join(', ')+(o.atr?' · <span style="color:#dc2626;font-weight:700">ATRASADO</span>':'');
      info.style.display='';
    } else {
      info.innerHTML = '<span style="color:#dc2626">PV '+q+' não encontrado na carteira</span>';
      info.style.display='';
    }
  }
});
// Enter no campo digitável = seleciona o PV (mesma ação do select)
document.addEventListener('keydown', function(e){
  if(e.key!=='Enter') return;
  const inp = e.target.closest ? e.target.closest('#tbbP input[data-p="pvdig"]') : null;
  if(!inp) return;
  e.preventDefault();
  const tr = inp.closest('tr'); const ix = parseInt(tr.getAttribute('data-ix'),10);
  const p = progProdsCache[ix]; if(!p) return;
  const q = inp.value.trim();
  const o = pvLookup(q);
  if(!o){ alert('PV '+q+' não encontrado na carteira.'); return; }
  const sel = tr.querySelector('select[data-p="pv"]');
  if(sel){
    // adiciona a opção se o PV não estiver na lista e seleciona
    let opt = Array.prototype.find.call(sel.options, function(x){ return x.value===o.pv+'|'+o.cli; }) || Array.prototype.find.call(sel.options, function(x){ return x.value===String(o.pv); });
    if(!opt){ opt = document.createElement('option'); opt.value = o.pv+'|'+o.cli; opt.textContent = o.pv+' · '+String(o.cli||'').slice(0,22); sel.appendChild(opt); }
    opt.selected = true;
    sel.dispatchEvent(new Event('change', {bubbles:true}));
  }
  const info = tr.querySelector('[data-p="pvdiginfo"]');
  if(info){ info.innerHTML = '<b>PV '+o.pv+'</b> selecionado — confirme a qtd realizada para registrar a saída'; info.style.display=''; }
  inp.value='';
});
// ==================== v0.0.202: AUTO-DETECÇÃO DE VERSÃO VELHA (cache CDN) ====================
// Sintoma do incidente 04/10: Dante com versão antiga em cache — botão Programar sem modal.
// O gerador estampa o build (b20261006224828); a página aberta confere a produção a cada 5 min e
// avisa (barra no topo) quando a versão publicada é mais nova. Recarrega com Ctrl+F5.
(function(){
  const BUILD=document.body.getAttribute('data-build')||'';
  function checkVer(){
    try{
      fetch(location.pathname+'?cb='+Date.now(), {cache:'no-store'}).then(function(r){ return r.text(); }).then(function(t){
        // o build REAL sempre aparece primeiro no atributo body data-build="..." (o código JS vem depois)
        const m = t.match(/data-build="([^"]+)"/);
        if(m && m[1] && m[1] !== BUILD){
          let bar = document.getElementById('verBar');
          if(!bar){
            bar = document.createElement('div');
            bar.id='verBar';
            bar.style.cssText='position:fixed;top:0;left:0;right:0;z-index:999;background:#b45309;color:#fff;font-size:13px;font-weight:700;padding:8px 16px;text-align:center;cursor:pointer';
            bar.textContent='⬆ Nova versão disponível — clique aqui para atualizar o painel';
            bar.addEventListener('click', function(){ location.reload(true); });
            document.body.appendChild(bar);
          }
          bar.style.display='block';
        }
      });
    }catch(e){}
  }
  checkVer();
  setInterval(checkVer, 300000);
})();

